<?php
require __DIR__.'/includes/init.php';
$pageTitle='Antrean & Order';
$allowedStatuses=['waiting','washing','drying','ironing','ready','completed','cancelled'];
$errors=[];
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
    $action=$_POST['action'] ?? '';
    if ($action==='add_order' || $action==='edit_order') {
        $code=trim($_POST['code'] ?? ''); $customer=trim($_POST['customer'] ?? ''); $phone=trim($_POST['phone'] ?? ''); $package=$_POST['package'] ?? 'Reguler'; $weight=(float)($_POST['weight'] ?? 0); $dateRaw=str_replace('T',' ',$_POST['dateIn'] ?? ''); $dateObj=DateTime::createFromFormat('Y-m-d H:i',$dateRaw); $status=$_POST['status'] ?? 'waiting'; $paid=isset($_POST['paid']);
        if($customer==='')$errors[]='Nama pelanggan wajib diisi.';
        if(!in_array($package,['Reguler','Express'],true))$errors[]='Paket layanan tidak valid.';
        if($weight<=0||$weight>200)$errors[]='Berat harus lebih dari 0 dan maksimal 200 kg.';
        if(!$dateObj)$errors[]='Tanggal masuk tidak valid.';
        if($action==='edit_order'&&!in_array($status,$allowedStatuses,true))$errors[]='Status order tidak valid.';
        $idx=$code!==''?findOrderIndex($code):null;
        if($action==='edit_order'&&$idx===null)$errors[]='Transaksi tidak ditemukan.';
        if(!$errors){$rate=$package==='Express'?14000:7000;$hours=$package==='Express'?12:48;$deadline=clone $dateObj;$deadline->modify('+'.$hours.' hours');
            if($action==='add_order'){$day=$dateObj->format('Ymd');$seq=1;foreach($_SESSION['laundry_orders'] as $o)if(strpos($o['code'],'LD-'.$day.'-')===0)$seq++;$code='LD-'.$day.'-'.str_pad((string)$seq,3,'0',STR_PAD_LEFT);$_SESSION['laundry_orders'][]=['code'=>$code,'customer'=>$customer,'phone'=>$phone,'package'=>$package,'weight'=>$weight,'dateIn'=>$dateObj->format('Y-m-d H:i:s'),'deadline'=>$deadline->format('Y-m-d H:i:s'),'status'=>'waiting','rate'=>$rate,'paid'=>false];$_SESSION['laundry_notifications'][]=['type'=>'new','code'=>$code,'message'=>'Order baru dibuat untuk '.$customer,'time'=>date('Y-m-d H:i:s')];flash('Transaksi '.$code.' berhasil ditambahkan.');}
            else{$oldStatus=$_SESSION['laundry_orders'][$idx]['status'];$_SESSION['laundry_orders'][$idx]=array_merge($_SESSION['laundry_orders'][$idx],['customer'=>$customer,'phone'=>$phone,'package'=>$package,'weight'=>$weight,'dateIn'=>$dateObj->format('Y-m-d H:i:s'),'deadline'=>$deadline->format('Y-m-d H:i:s'),'status'=>$status,'rate'=>$rate,'paid'=>$paid]);if($status==='ready'&&$oldStatus!=='ready')$_SESSION['laundry_notifications'][]=['type'=>'ready','code'=>$code,'message'=>'Cucian siap diambil: '.$customer,'time'=>date('Y-m-d H:i:s')];flash('Transaksi '.$code.' berhasil diperbarui.');}
            header('Location: antrean.php');exit;
        }
        $_SESSION['queue_modal_error']=['errors'=>$errors,'action'=>$action,'post'=>$_POST];
        header('Location: antrean.php?modal='.($action==='add_order'?'add':'edit').'&code='.urlencode($code));exit;
    }
}
$orders=$_SESSION['laundry_orders'];sortOrders($orders);$query=trim($_GET['q']??'');$status=$_GET['status']??'all';$filtered=array_values(array_filter($orders,function($o)use($query,$status){$matchQuery=$query===''||stripos($o['code'],$query)!==false||stripos($o['customer'],$query)!==false||stripos($o['phone'],$query)!==false;$matchStatus=$status==='all'||$o['status']===$status;return $matchQuery&&$matchStatus;}));$perPage=5;$totalFiltered=count($filtered);$pages=max(1,(int)ceil($totalFiltered/$perPage));$page=max(1,min($pages,(int)($_GET['page']??1)));$pageOrders=array_slice($filtered,($page-1)*$perPage,$perPage);
$modalError=$_SESSION['queue_modal_error']??null;unset($_SESSION['queue_modal_error']);$addPost=($modalError['action']??'')==='add_order'?($modalError['post']??[]):[];$editPost=($modalError['action']??'')==='edit_order'?($modalError['post']??[]):[];
require __DIR__.'/includes/header.php'; ?>
