me="dateIn" type="datetime-local" value="<?= e($addPost['dateIn']??date('Y-m-d\TH:i')) ?>" required></div><div class="col-md-6"><label class="form-label">Estimasi deadline</label><div class="deadline-hint"><i class="bi bi-clock-history"></i> Reguler 48 jam · Express 12 jam</div></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light border" data-bs-dismiss="modal">Batal</button><button class="btn btn-brand" type="submit"><i class="bi bi-check2-circle me-2"></i>Simpan transaksi</button></div></form></div></div></div>
